const stalePayouts = `-- name: StalePayouts :many
SELECT id, status FROM payouts.payouts
WHERE status IN ('pending','sending','sent','timed_out','result_received') AND updated_at < $1
ORDER BY updated_at LIMIT 200
`

type StalePayoutsRow struct {
	ID     string
	Status string
}

// payouts the worker should look at again: still open and untouched for a while
func (q *Queries) StalePayouts(ctx context.Context, before time.Time) ([]StalePayoutsRow, error) {
	rows, err := q.db.Query(ctx, stalePayouts, before)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StalePayoutsRow
	for rows.Next() {
		var i StalePayoutsRow
		if err := rows.Scan(&i.ID, &i.Status); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

